// Generates ui_kit Dart tokens from docs/design/tokens.json.
//
// Run from the repo root: `melos run tokens` (generates, then formats).
import 'dart:convert';
import 'dart:io';

const _source = 'docs/design/tokens.json';
const _outDir = 'packages/ui_kit/lib/src/tokens';
const _header =
    '// GENERATED by tool/gen_tokens.dart from $_source. '
    'Do not edit.\n// Run `melos run tokens` after changing the JSON.\n\n';

typedef _Json = Map<String, dynamic>;

void main() {
  final json = jsonDecode(File(_source).readAsStringSync()) as _Json;
  final files = {
    'bk_colors.g.dart': _colors(json['color'] as _Json),
    'bk_typography.g.dart': _typography(json['type'] as _Json),
    'bk_spacing.g.dart': _scale(
      json['spacing'] as _Json,
      'BkSpacing',
      'Spacing scale in logical pixels.',
      'space-',
      's',
    ),
    'bk_radius.g.dart': _scale(
      json['radius'] as _Json,
      'BkRadius',
      'Corner radii in logical pixels.',
      'radius-',
      '',
    ),
    'bk_shadows.g.dart': _shadows(json['shadow'] as _Json),
  };
  for (final MapEntry(:key, :value) in files.entries) {
    File('$_outDir/$key').writeAsStringSync(_header + value);
  }
  stdout.writeln('Wrote ${files.length} files to $_outDir');
}

List<_Json> _tokens(_Json group) =>
    (group['tokens'] as List<dynamic>).cast<_Json>();

/// `bucket-fun` → `bucketFun`, `title-1` → `title1`.
String _camel(String kebab) {
  final parts = kebab.split('-');
  return parts.first +
      parts.skip(1).map((p) => p[0].toUpperCase() + p.substring(1)).join();
}

/// `16px` → `16`.
num _px(String value) => num.parse(value.replaceAll('px', ''));

/// `#RRGGBB` or `rgba(r,g,b,a)` → `Color(0xAARRGGBB)`.
String _color(String css) {
  if (css.startsWith('#') && css.length == 7) {
    return 'Color(0xFF${css.substring(1).toUpperCase()})';
  }
  final rgba = RegExp(
    r'^rgba\((\d+),(\d+),(\d+),([\d.]+)\)$',
  ).firstMatch(css.replaceAll(' ', ''));
  if (rgba == null) throw FormatException('Unsupported color', css);
  final alpha = (double.parse(rgba[4]!) * 255).round();
  final hex = [
    alpha,
    ...[1, 2, 3].map((i) => int.parse(rgba[i]!)),
  ].map((c) => c.toRadixString(16).padLeft(2, '0')).join().toUpperCase();
  return 'Color(0x$hex)';
}

String _doc(_Json token) =>
    token['usage'] == null ? '' : '  /// ${token['usage']}\n';

String _colorArg(_Json token, String theme) {
  final value = _color((token['value'] as _Json)[theme] as String);
  return '    ${_camel(token['name'] as String)}: $value,';
}

String _colors(_Json group) {
  final tokens = _tokens(group);
  final names = [for (final t in tokens) _camel(t['name'] as String)];
  String theme(String id) => [
    for (final t in tokens) _colorArg(t, id),
  ].join('\n');
  return '''
import 'package:flutter/material.dart';

/// Color tokens for the light and dark themes.
class BkColors extends ThemeExtension<BkColors> {
  /// Creates a color set. Use [light] or [dark].
  const BkColors({${names.map((n) => 'required this.$n').join(', ')}});

  /// Light theme colors.
  static const light = BkColors(
${theme('light')}
  );

  /// Dark theme colors.
  static const dark = BkColors(
${theme('dark')}
  );

${[for (final t in tokens) '${_doc(t)}  final Color ${_camel(t['name'] as String)};'].join('\n\n')}

  @override
  BkColors copyWith({${names.map((n) => 'Color? $n').join(', ')}}) => BkColors(
${names.map((n) => '    $n: $n ?? this.$n,').join('\n')}
  );

  @override
  BkColors lerp(BkColors? other, double t) {
    if (other == null) return this;
    return BkColors(
${names.map((n) => '      $n: Color.lerp($n, other.$n, t)!,').join('\n')}
    );
  }
}
''';
}

/// First quoted family name: `"Geist", "Inter", …` → `Geist`.
String _family(String css) => RegExp('"([^"]+)"').firstMatch(css)![1]!;

String _textStyle(_Json style, String family, {required bool tabular}) {
  final size = _px(style['fontSize'] as String);
  final spacing = style['letterSpacing'] as String?;
  return [
    "    fontFamily: '$family',",
    '    fontSize: $size,',
    '    height: ${_px(style['lineHeight'] as String)} / $size,',
    '    fontWeight: FontWeight(${style['fontWeight']}),',
    if (spacing != null)
      '    letterSpacing: ${spacing.replaceAll('em', '')} * $size,',
    if (tabular) '    fontFeatures: [FontFeature.tabularFigures()],',
  ].join('\n');
}

String _styleField(_Json group, _Json style, String family) {
  final name = _camel(style['name'] as String);
  final body = _textStyle(style, family, tabular: group['name'] == 'Numbers');
  return '  /// ${group['name']}: ${style['name']}.\n'
      '  static const $name = TextStyle(\n$body\n  );';
}

String _typography(_Json type) {
  final families = (type['families'] as _Json).map(
    (key, value) => MapEntry(key, _family(value as String)),
  );
  final fields = [
    for (final group in (type['groups'] as List<dynamic>).cast<_Json>())
      for (final style in (group['styles'] as List<dynamic>).cast<_Json>())
        _styleField(group, style, families[group['family']]!),
  ];
  return '''
import 'package:flutter/painting.dart';

/// Text styles. Colors come from the theme, not from these styles.
abstract final class BkTypography {
${fields.join('\n\n')}
}
''';
}

String _scaleField(_Json token, String prefix, String to) {
  final name = _camel(to + (token['name'] as String).substring(prefix.length));
  return '${_doc(token)}  static const double $name = '
      '${_px(token['value'] as String)};';
}

String _scale(_Json group, String type, String doc, String prefix, String to) {
  final fields = [
    for (final t in _tokens(group)) _scaleField(t, prefix, to),
  ];
  return '/// $doc\nabstract final class $type {\n${fields.join('\n\n')}\n}\n';
}

String _boxShadow(RegExpMatch m) =>
    '    BoxShadow(offset: Offset(${m[1]}, ${m[2]}), blurRadius: ${m[3]}, '
    'color: ${_color(m[4]!)}),';

String _shadowField(_Json token) {
  final name = _camel((token['name'] as String).substring('shadow-'.length));
  return '${_doc(token)}  static const $name = <BoxShadow>[\n'
      '${_boxShadows(token['value'] as String)}\n  ];';
}

/// `0 1px 2px rgba(…), …` → `BoxShadow(…)` list items.
String _boxShadows(String css) => [
  for (final m in RegExp(
    r'(-?[\d.]+)(?:px)? (-?[\d.]+)(?:px)? (-?[\d.]+)(?:px)? (rgba\([^)]*\))',
  ).allMatches(css))
    _boxShadow(m),
].join('\n');

String _shadows(_Json group) {
  final fields = [
    for (final t in _tokens(group)) _shadowField(t),
  ];
  return '''
import 'package:flutter/painting.dart';

/// Elevation shadows.
abstract final class BkShadows {
${fields.join('\n\n')}
}
''';
}
